select
a.rp_id,
a.menu_code,
a.sort,
a.element_code,
a.role_id
from sys_role_menu a
where 1 = 1
 and a.rp_id = #{rpId, jdbcType=BIGINT}
 and a.menu_code = #{menuCode, jdbcType=VARCHAR}
 and a.sort = #{sort, jdbcType=INTEGER}
 and a.element_code = #{elementCode, jdbcType=VARCHAR}
 and a.role_id = #{roleId, jdbcType=BIGINT}

